export function finite(n){if(!Number.isFinite(n))throw Error('The result is outside the supported range. Check the inputs.');return n}
export function emi(principal,annualRate,months){if(principal<0||annualRate<0||!Number.isInteger(months)||months<1||months>1200)throw Error('Use non-negative amounts and a term of 1–1,200 whole months.');const r=annualRate/1200;const payment=r?principal*r/(1-Math.pow(1+r,-months)):principal/months;let balance=principal;const schedule=[];for(let m=1;m<=months;m++){const interest=balance*r;const paid=Math.min(payment,balance+interest);const capital=paid-interest;balance=Math.max(0,balance-capital);schedule.push([m,paid,capital,interest,balance])}return {payment:finite(payment),interest:finite(payment*months-principal),total:finite(payment*months),schedule}}
export function futureValue({principal=0,monthly=0,annual=0,months=12,frequency=12,timing='end',step=0}){if(annual<=-100||principal<0||monthly<0||step<=-100||months<0||months>1200||!Number.isInteger(months)||frequency<1)throw Error('Use valid amounts, a whole-month term up to 100 years, and rates above −100%.');const r=Math.pow(1+annual/100/frequency,frequency/12)-1;let balance=principal,contributed=principal;for(let m=0;m<months;m++){const c=monthly*Math.pow(1+step/100,Math.floor(m/12));if(timing==='beginning')balance+=c;balance*=1+r;if(timing==='end')balance+=c;contributed+=c}return {value:finite(balance),contributed:finite(contributed),interest:finite(balance-contributed)}}
export function parseDate(s){if(!/^\d{4}-\d{2}-\d{2}$/.test(s))throw Error('Enter a complete date.');const [y,m,d]=s.split('-').map(Number);const date=new Date(Date.UTC(y,m-1,d));if(date.getUTCFullYear()!==y||date.getUTCMonth()!==m-1||date.getUTCDate()!==d)throw Error('Enter a valid date between years 0100 and 9999.');return date}
export function addMonthsClamped(date,count){const y=date.getUTCFullYear(),m=date.getUTCMonth()+count;const first=new Date(Date.UTC(y,m,1));const last=new Date(Date.UTC(first.getUTCFullYear(),first.getUTCMonth()+1,0)).getUTCDate();first.setUTCDate(Math.min(last,date.getUTCDate()));return first}
export function ageBetween(start,end){if(end<start)throw Error('The end date must be on or after the start date.');let months=(end.getUTCFullYear()-start.getUTCFullYear())*12+end.getUTCMonth()-start.getUTCMonth();if(addMonthsClamped(start,months)>end)months--;const anchor=addMonthsClamped(start,months);return {years:Math.floor(months/12),months:months%12,days:Math.round((end-anchor)/86400000),totalDays:Math.round((end-start)/86400000)}}
export function timeMinutes(s){if(!/^\d{2}:\d{2}$/.test(s))throw Error('Enter both times.');const [h,m]=s.split(':').map(Number);if(h>23||m>59)throw Error('Invalid time.');return h*60+m}
export function duration(start,end,breaks=0,overnight=false){let total=timeMinutes(end)-timeMinutes(start);if(overnight)total+=1440;if(total<0)throw Error('End time is earlier. Enable next-day end if the shift crosses midnight.');if(breaks<0||breaks>total)throw Error('Breaks must be between zero and the shift duration.');return total-breaks}
export function pageRanges(text,count){if(!text.trim())throw Error('Enter page numbers or ranges.');const result=[];for(const part of text.split(',')){const m=part.trim().match(/^(\d+)(?:\s*-\s*(\d+))?$/);if(!m)throw Error('Use ranges such as 1-3,5,8-9.');const a=+m[1],b=m[2]?+m[2]:a;if(a<1||b<a||b>count)throw Error(`Page ranges must be between 1 and ${count}, in ascending order.`);for(let i=a;i<=b;i++)result.push(i-1)}return [...new Set(result)]}
export function safeCell(v){return typeof v==='string'&&/^[\s]*[=+@-]/.test(v)?"'"+v:v}
export function scientific(expression,degrees=true){if(typeof expression!=='string'||expression.length>500)throw Error('Enter an expression under 500 characters.');const src=expression.replace(/π/g,'pi').replace(/×/g,'*').replace(/÷/g,'/').replace(/−/g,'-');const tokens=[];let p=0;while(p<src.length){if(/\s/.test(src[p])){p++;continue}const m=src.slice(p).match(/^(?:(\d*\.\d+|\d+\.?\d*)(?:[eE]([+-]?\d+))?|([a-z]+)|([+\-*/^()%]))/);if(!m)throw Error('Only mathematical numbers, operators and supported functions are allowed.');tokens.push(m[0]);p+=m[0].length}let i=0;const peek=()=>tokens[i],eat=()=>tokens[i++];let depth=0;function primary(){if(++depth>60)throw Error('Expression is too deeply nested.');let v;const t=eat();if(t==='('){v=sum();if(eat()!==')')throw Error('Close every parenthesis.')}else if(t==='pi')v=Math.PI;else if(t==='e')v=Math.E;else if(/^(sin|cos|tan|log|ln|sqrt)$/.test(t||'')){if(eat()!=='(')throw Error('Functions need parentheses.');const x=sum();if(eat()!==')')throw Error('Close every function parenthesis.');const angle=degrees?x*Math.PI/180:x;if(t==='tan'&&Math.abs(Math.cos(angle))<1e-12)throw Error('Tangent is undefined at this angle.');v={sin:()=>Math.sin(angle),cos:()=>Math.cos(angle),tan:()=>Math.tan(angle),log:()=>Math.log10(x),ln:()=>Math.log(x),sqrt:()=>Math.sqrt(x)}[t]()}else if(t&&/^[\d.]/.test(t))v=Number(t);else throw Error('Expected a number, constant or function.');while(peek()==='%'){eat();v/=100}depth--;return v}function power(){let a=primary();if(peek()==='^'){eat();a=Math.pow(a,unary())}return a}function unary(){if(peek()==='+'){eat();return unary()}if(peek()==='-'){eat();return -unary()}return power()}function product(){let a=unary();while(['*','/'].includes(peek())){const op=eat(),b=unary();if(op==='/'&&b===0)throw Error('Cannot divide by zero.');a=op==='*'?a*b:a/b}return a}function sum(){let a=product();while(['+','-'].includes(peek())){const op=eat(),b=product();a=op==='+'?a+b:a-b}return a}const v=sum();if(i!==tokens.length)throw Error('Check the expression. Use * for multiplication.');return finite(v)}
export const unitGroups={length:{m:1,km:1000,cm:.01,mm:.001,in:.0254,ft:.3048,yd:.9144,mi:1609.344},weight:{kg:1,g:.001,mg:.000001,lb:.45359237,oz:.028349523125},area:{'m²':1,'km²':1e6,'ft²':.09290304,acre:4046.8564224,hectare:10000},volume:{L:1,mL:.001,'m³':1000,'US gallon':3.785411784,'UK gallon':4.54609},data:{byte:1,bit:.125,KB:1000,MB:1e6,GB:1e9,KiB:1024,MiB:1048576,GiB:1073741824},temperature:{C:1,F:1,K:1}};
export function convertUnit(value,group,from,to){if(!unitGroups[group]||!(from in unitGroups[group])||!(to in unitGroups[group]))throw Error('Choose valid units.');if(group==='temperature'){const c=from==='C'?value:from==='F'?(value-32)*5/9:value-273.15;if(c< -273.15)throw Error('Temperature cannot be below absolute zero.');return to==='C'?c:to==='F'?c*9/5+32:c+273.15}return finite(value*unitGroups[group][from]/unitGroups[group][to])}
